3	//! The `POST /v1/chat/completions` proxy handler — the integration crux of the M0 slice.
4	//!
5	//! By the time this runs, the G5 [`require_iam_auth`](super::auth::require_iam_auth) middleware has
6	//! already authenticated + authorized the caller and attached a [`CallerContext`] to the request
7	//! extensions. This handler's job is narrow and security-sensitive:
8	//!
9	//! 1. Read the full request body as raw [`EnvelopeBytes`] — the body-size limit is enforced by
10	//!    the [`DefaultBodyLimit`](axum::extract::DefaultBodyLimit) layer, which `EnvelopeBytes`
11	//!    honours and reports as a `413` INSIDE the OpenAI envelope (SMA-588); before that it was
12	//!    axum's plain text, outside the error contract.
13	//! 2. Parse a COPY of the body into [`ChatCompletionRequest`] ONLY to read `model` (logging) and
14	//!    `stream` (which egress path to take). A JSON parse failure → `400`.
15	//! 3. **Egress hygiene (load-bearing):** forward ONLY the raw body bytes to the OpenAI client —
16	//!    NEVER the caller's inbound headers. The caller's `Authorization: Bearer <paigasus-key>` is
17	//!    still on the inbound request; it must never reach OpenAI. The client builds fresh upstream
18	//!    headers from its own real key, so simply never handing it caller headers guarantees this.
19	//! 4. Forward the upstream response verbatim: a full body (non-stream) or an UNBUFFERED SSE stream.
20	//!    A non-2xx upstream (OpenAI's own error envelope) passes through unchanged.
21	//!
22	//! ## Mid-stream terminal SSE error (spec §5)
23	//! Once a stream's `200 OK` head has been sent and `data:` frames are flowing, the HTTP status can
24	//! no longer change — so a mid-stream upstream failure cannot become a `502`. Instead the stream is
25	//! adapted so that on the FIRST inner error it emits one terminal
26	//! `data: {"error":…}` SSE event and then ends. The adapted stream is returned DIRECTLY (never
27	//! spawned onto a detached task) so reqwest's cancel-on-drop stays intact: if the downstream client
28	//! disconnects, axum drops the response body, which drops the inner reqwest stream and cancels the
29	//! upstream request (G8 proves this abort).
30	
31	use std::convert::Infallible;
32	
33	use axum::Extension;
34	use axum::body::Bytes;
35	use axum::extract::State;
36	use axum::response::{IntoResponse, Response};
37	use futures::{Stream, StreamExt};
38	use paigasus_gateway_core::Format;
39	
40	use super::AppState;
41	use super::error::GatewayError;
42	use super::pipeline::{self, Endpoint, RequestFacts};
43	use crate::adapters::http::bytes::EnvelopeBytes;
44	use crate::adapters::http::dto::ChatCompletionRequest;
45	use crate::adapters::http::usage::{self, StreamUsage, UsageScanner};
46	use crate::adapters::openai::{OpenAiByteStream, UpstreamRoute};
47	use crate::application::charge_guard::ChargeGuard;
48	use crate::domain::CallerContext;
49	
50	/// The single terminal SSE event emitted when a stream fails mid-flight. Static, caller-safe (no
51	/// upstream detail), and shaped like the OpenAI error envelope wrapped in an SSE `data:` frame so
52	/// SDKs that parse the stream see a well-formed terminal error. `code` is the registry's kebab
53	/// `upstream-error` (SMA-504).
54	///
55	/// This frame carries NO `paigasus-retryable` header: by the time it is emitted, the `200 OK`
56	/// head is already committed, so no header can change at this point. Nor does its JSON gain a
57	/// `retryable` key — that would add a field the OpenAI envelope shape (AC 3) does not have, on
58	/// this one frame only. Retryability is derivable anyway without either mechanism: `upstream-error`
59	/// is by construction the transient mid-stream case (the request already reached the upstream and
60	/// was streaming successfully before it failed), so a client that recognizes this code already
61	/// knows it may retry.
62	///
63	/// The frame STARTS with a blank line (SMA-635 spec §4.6). An upstream failure can fall inside a
64	/// record; without the blank line the frame would join that partial record and no SSE parser
65	/// could read it. After a clean record boundary the extra blank line is an empty record, which
66	/// dispatches nothing, so a client that reads a clean boundary sees no change.
67	pub(crate) const TERMINAL_SSE_ERROR: &str = "\n\ndata: {\"error\":{\"message\":\"upstream stream error\",\"type\":\"api_error\",\"param\":null,\"code\":\"upstream-error\"}}\n\n";
68	
69	/// Proxy a chat-completion request to the OpenAI upstream.
70	///
71	/// Extractor order matters: [`State`] and [`Extension`] are `FromRequestParts` (they read only the
72	/// head), while [`EnvelopeBytes`] is `FromRequest` (it consumes the body) and so must come LAST.
73	/// [`EnvelopeBytes`] wraps [`Bytes`], so it honours the
74	/// [`DefaultBodyLimit`](axum::extract::DefaultBodyLimit) layer the same way and returns `413`
75	/// for an over-limit body before this function body runs — rendered through the OpenAI envelope
76	/// rather than as axum's plain text (SMA-588). It is still `FromRequest`, so it must come LAST.
77	///
78	/// `CallerContext` is taken as `Option<Extension<_>>` for defence in depth: the G5 middleware
79	/// guarantees its presence on any request routed here, so its absence is an unreachable internal
80	/// bug surfaced as a `500` (rendered through the OpenAI envelope) rather than axum's default
81	/// extension-missing response.
82	///
83	/// The flow itself is [`pipeline::proxy`]; this handler only supplies the [`CHAT`] descriptor.
84	pub(crate) async fn chat_completions(State(state): State<AppState>, caller: Option<Extension<CallerContext>>, EnvelopeBytes(body): EnvelopeBytes) -> Response {
85	    let Some(Extension(caller)) = caller else {
86	        // Unreachable in practice — the auth middleware always attaches a CallerContext.
87	        return GatewayError::Internal.into_response();
88	    };
89	    pipeline::proxy(&CHAT, state, caller, body).await
90	}
91	
92	/// The descriptor of `POST /v1/chat/completions`.
93	pub static CHAT: Endpoint = Endpoint {
94	    name: "chat_completions",
95	    route: UpstreamRoute::ChatCompletions,
96	    format: Format::OpenAiChat,
97	    parse: parse_chat,
98	    non_stream_usage: usage::non_stream_usage,
99	    stream_usage: || StreamUsage::Chat(UsageScanner::new()),
100	    terminal: TERMINAL_SSE_ERROR,
101	    limits: |ti, _state| ti.limits,
102	};
103	
104	/// Parse a COPY of the body only to read `model` and `stream`; the ORIGINAL bytes flow upstream
105	/// verbatim. SMA-588 splits the failure: `serde_json` classifies its own errors, so a body that
106	/// PARSED but did not match the type is reported distinctly from one that could not be read at
107	/// all. `Category::Io` cannot arise from a `&[u8]`, but is grouped with the unreadable cases so
108	/// the match is exhaustive without a wildcard.
109	fn parse_chat(body: &[u8], _interception: bool) -> Result<RequestFacts, GatewayError> {
110	    let dto: ChatCompletionRequest = match serde_json::from_slice(body) {
111	        Ok(dto) => dto,
112	        Err(e) => {
113	            return Err(match e.classify() {
114	                serde_json::error::Category::Data => GatewayError::InvalidRequestSchema,
115	                serde_json::error::Category::Syntax | serde_json::error::Category::Eof | serde_json::error::Category::Io => GatewayError::BadRequestBody,
116	            });
117	        }
118	    };
119	    Ok(RequestFacts {
120	        request_estimate: usage::request_tokens_estimate(&dto.messages, body.len()),
121	        model: dto.model,
122	        stream: dto.stream,
123	    })
124	}
125	
126	/// The small state machine [`terminal_sse_error_stream`] unfolds over: still forwarding upstream
127	/// chunks, or terminated (after emitting the terminal error event, or after the upstream ended).
128	enum StreamState {
129	    Streaming(OpenAiByteStream),
130	    Done,
131	}
132	
133	/// The unfold state. The charge guard is a FIELD here, not a `Drop` on `StreamState`: the closure
134	/// destructures the state by move, which a type with `Drop` forbids (E0509). When the stream ends,
135	/// fails, or is dropped, this value drops once, and the guard with it (SMA-677 § 4.6). The clean
136	/// end and the first error call `UsageScanner::finish()` first; a drop (client disconnect) does
137	/// not, so a last record with no blank line counts only when the upstream ended (SMA-730 D3).
138	struct Relay {
139	    phase: StreamState,
140	    scan: StreamUsage,
141	    guard: Option<ChargeGuard>,
142	}
143	
144	/// One upstream chunk, read for billing before anything else sees it (SMA-677, SMA-749 D24).
145	/// Without a guard (no `[limits]`) nothing is parsed at all. Shared with the intercepting relay.
146	pub(crate) fn feed_scan(scan: &mut StreamUsage, guard: &mut Option<ChargeGuard>, chunk: &[u8]) {
147	    if let Some(guard) = guard.as_mut() {
148	        scan.feed(chunk);
149	        guard.set_stream_progress(scan.completion_records(), scan.reported_total());
150	    }
151	}
152	
153	/// SMA-730: the upstream ended or failed. A last record with no blank line after it still
154	/// counts. Without a guard the scanner reads nothing, as in the chunk arm. Shared with the
155	/// intercepting relay (SMA-749 D24).
156	pub(crate) fn finish_scan(scan: &mut StreamUsage, guard: &mut Option<ChargeGuard>) {
157	    if let Some(guard) = guard.as_mut() {
158	        scan.finish();
159	        guard.set_stream_progress(scan.completion_records(), scan.reported_total());
160	    }
161	}
162	
163	/// Adapt an [`OpenAiByteStream`] into a body stream that forwards each upstream chunk UNBUFFERED
164	/// and, on the FIRST upstream error, emits one terminal [`TERMINAL_SSE_ERROR`] event and ends.
165	///
166	/// Items are `Result<Bytes, Infallible>`: the outgoing stream never errors (a mid-stream upstream
167	/// failure becomes a data event, not a transport error), which keeps `Body::from_stream` from
168	/// aborting the response body. The inner stream is owned by the unfold state and dropped when this
169	/// stream is dropped — preserving reqwest's cancel-on-drop of the upstream request.
170	///
171	/// Runs with `paigasus_observability::current_ids() == None` (SMA-504 spec §4.3, situation 3):
172	/// this function is polled by hyper after the request-head future — the one the
173	/// `CorrelationLayer` task-local scope covers — has already resolved. See the call site's
174	/// comment in `chat_completions`.
175	pub(crate) fn terminal_sse_error_stream(
176	    inner: OpenAiByteStream,
177	    guard: Option<ChargeGuard>,
178	    usage: StreamUsage,
179	    terminal: &'static str,
180	) -> impl Stream<Item = Result<Bytes, Infallible>> + Send + 'static {
181	    let start = Relay {
182	        phase: StreamState::Streaming(inner),
183	        scan: usage,
184	        guard,
185	    };
186	    futures::stream::unfold(start, move |Relay { phase, mut scan, mut guard }| async move {
187	        match phase {
188	            StreamState::Streaming(mut inner) => match inner.next().await {
189	                // Forward each chunk exactly as it arrived (unbuffered). The scanner reads a copy,
190	                // and only when a guard exists (no `[limits]`: no parsing at all).
191	                Some(Ok(chunk)) => {
192	                    feed_scan(&mut scan, &mut guard, &chunk);
193	                    Some((
194	                        Ok(chunk),
195	                        Relay {
196	                            phase: StreamState::Streaming(inner),
197	                            scan,
198	                            guard,
199	                        },
200	                    ))
201	                }
202	                // First upstream error: count the last record (the frame's leading blank line
203	                // closes it for the client too), emit the terminal event, then end.
204	                Some(Err(_)) => {
205	                    finish_scan(&mut scan, &mut guard);
206	                    Some((
207	                        Ok(Bytes::from_static(terminal.as_bytes())),
208	                        Relay {
209	                            phase: StreamState::Done,
210	                            scan,
211	                            guard,
212	                        },
213	                    ))
214	                }
215	                // Clean upstream end: count the last record, then drop the relay and the guard.
216	                None => {
217	                    finish_scan(&mut scan, &mut guard);
218	                    None
219	                }
220	            },
221	            StreamState::Done => None,
222	        }
223	    })
224	}
