226	#[cfg(test)]
227	pub(crate) mod tests {
228	    use super::*;
229	
230	    /// The plain relay as the pipeline builds it for chat (no interception).
231	    fn plain_relay(inner: OpenAiByteStream, guard: Option<ChargeGuard>) -> impl Stream<Item = Result<Bytes, Infallible>> + Send + 'static {
232	        terminal_sse_error_stream(inner, guard, StreamUsage::Chat(UsageScanner::new()), TERMINAL_SSE_ERROR)
233	    }
234	
235	    /// Section 4.6: the relay never changes a forwarded byte, with or without a scanner (A5).
236	    #[tokio::test]
237	    async fn the_relay_forwards_bytes_unchanged() {
238	        let chunks = vec![Ok(Bytes::from_static(b"data: {\"usage\":{\"total_tokens\":3}}\r\n")), Ok(Bytes::from_static(b"\r\ndata: [DONE]\n\n"))];
239	        let out: Vec<Bytes> = plain_relay(futures::stream::iter(chunks).boxed(), None).map(|r| r.unwrap()).collect().await;
240	        assert_eq!(out.concat(), b"data: {\"usage\":{\"total_tokens\":3}}\r\n\r\ndata: [DONE]\n\n".to_vec());
241	    }
242	
243	    #[tokio::test]
244	    async fn terminal_stream_forwards_chunks_then_ends_cleanly() {
245	        // A clean upstream stream (no error) is forwarded chunk-for-chunk with no terminal event.
246	        let inner = futures::stream::iter(vec![Ok(Bytes::from_static(b"data: a\n\n")), Ok(Bytes::from_static(b"data: b\n\n"))]).boxed();
247	        let out: Vec<Bytes> = plain_relay(inner, None).map(|r| r.unwrap()).collect().await;
248	        let assembled: Vec<u8> = out.iter().flat_map(|b| b.to_vec()).collect();
249	        assert_eq!(String::from_utf8(assembled).unwrap(), "data: a\n\ndata: b\n\n");
250	    }
251	
252	    #[tokio::test]
253	    async fn terminal_stream_emits_terminal_event_on_first_error_then_stops() {
254	        // After the first upstream error the adapter emits exactly one terminal event and ends —
255	        // any items the upstream would have produced afterwards are never observed.
256	        let inner = futures::stream::iter(vec![Ok(Bytes::from_static(b"data: a\n\n"))])
257	            .chain(futures::stream::once(async { Err(make_reqwest_error().await) }))
258	            .boxed();
259	        let out: Vec<Bytes> = plain_relay(inner, None).map(|r| r.unwrap()).collect().await;
260	        let assembled: Vec<u8> = out.iter().flat_map(|b| b.to_vec()).collect();
261	        let text = String::from_utf8(assembled).unwrap();
262	        assert!(text.starts_with("data: a\n\n"), "the pre-error chunk is forwarded: {text}");
263	        assert!(text.ends_with(TERMINAL_SSE_ERROR), "the stream ends with exactly the terminal SSE error event: {text}");
264	        assert_eq!(text.matches("\"code\":\"upstream-error\"").count(), 1, "exactly one terminal error event");
265	    }
266	
267	    /// SMA-635 spec §4.6: an upstream failure INSIDE a record must not join the terminal frame to
268	    /// the partial record. The frame starts with a blank line, so it is a record of its own and
269	    /// parses as JSON by itself.
270	    #[tokio::test]
271	    async fn the_terminal_frame_is_its_own_record_after_a_partial_one() {
272	        let inner = futures::stream::iter(vec![Ok(Bytes::from_static(b"data: {\"choices\":[{\"delta\":{\"content\":\"par"))])
273	            .chain(futures::stream::once(async { Err(make_reqwest_error().await) }))
274	            .boxed();
275	        let out: Vec<Bytes> = plain_relay(inner, None).map(|r| r.unwrap()).collect().await;
276	        let text = String::from_utf8(out.iter().flat_map(|b| b.to_vec()).collect()).unwrap();
277	        let records: Vec<&str> = text.split("\n\n").filter(|record| !record.is_empty()).collect();
278	        let last = records.last().expect("at least one record");
279	        let payload = last.strip_prefix("data: ").expect("the last record is a data record of its own");
280	        let parsed: serde_json::Value = serde_json::from_str(payload).expect("the terminal record parses as JSON on its own");
281	        assert_eq!(parsed["error"]["code"], "upstream-error");
282	    }
283	
284	    /// AC 6 for the terminal SSE frame. Parses the frame's JSON and resolves the `code` field
285	    /// rather than string-comparing the same literal the constant is built from — a comparison
286	    /// against the literal would pass even if the code were never registered.
287	    #[test]
288	    fn the_terminal_sse_frame_carries_a_registered_code() {
289	        use paigasus_proto::paigasus::common::v1::ErrorReason;
290	
291	        let payload = TERMINAL_SSE_ERROR.trim_start_matches('\n').strip_prefix("data: ").expect("an SSE data frame").trim_end();
292	        let parsed: serde_json::Value = serde_json::from_str(payload).expect("the frame must be valid JSON");
293	        let code = parsed["error"]["code"].as_str().expect("a code");
294	        assert!(ErrorReason::from_wire_reason(code).is_some(), "{code} is not declared in common/v1/error.proto");
295	        assert_eq!(parsed["error"]["type"], "api_error", "the frame keeps the OpenAI envelope shape");
296	    }
297	
298	    use crate::application::charge_guard::{ChargeGuard, NoTicket};
299	    use crate::application::limits::Limits;
300	    use crate::domain::limits::{BudgetPeriod, LimitDecision, LimitRules, LimitStoreError, LimitTicket};
301	    use crate::test_support::{FixedClock, ORG_A, ScriptedStore, at};
302	    use std::sync::Arc;
303	
304	    pub(crate) fn admit() -> Result<LimitDecision, LimitStoreError> {
305	        Ok(LimitDecision::Admit(None))
306	    }
307	
308	    /// A sent guard with a ticket and a request estimate of 1, charging into `store`.
309	    pub(crate) fn sent_guard(store: &Arc<ScriptedStore>) -> ChargeGuard {
310	        let now = at("2026-10-02T12:00:00Z");
311	        let limits = Arc::new(Limits::new(LimitRules::default(), store.clone(), Arc::new(FixedClock(now))));
312	        let ticket = LimitTicket {
313	            org: ORG_A,
314	            period: BudgetPeriod::Monthly.key_at(now),
315	        };
316	        let mut guard = ChargeGuard::new(limits, Some(ticket), Some(ORG_A), NoTicket::NoBudget);
317	        guard.set_request_estimate(1);
318	        guard.mark_sent();
319	        guard
320	    }
321	
322	    pub(crate) const UNTERMINATED_USAGE: &[u8] = b"data: {\"choices\":[],\"usage\":{\"total_tokens\":7}}";
323	
324	    /// SMA-730 R1 (spec D2): an upstream error after a usage record with no blank line charges
325	    /// the reported total. The terminal frame closes that record for the client too.
326	    #[tokio::test]
327	    async fn an_error_after_an_unterminated_usage_record_charges_the_reported_tokens() {
328	        let store = ScriptedStore::new(admit);
329	        let inner = futures::stream::iter(vec![Ok(Bytes::from_static(UNTERMINATED_USAGE))])
330	            .chain(futures::stream::once(async { Err(make_reqwest_error().await) }))
331	            .boxed();
332	        let out: Vec<Bytes> = plain_relay(inner, Some(sent_guard(&store))).map(|r| r.unwrap()).collect().await;
333	        assert!(out.concat().ends_with(TERMINAL_SSE_ERROR.as_bytes()));
334	        assert_eq!(store.charges(), vec![7]);
335	    }
336	
337	    /// SMA-730 R2 (spec D3): a client that disconnects drops the relay. The unterminated record
338	    /// does not count, and the guard charges the estimate.
339	    #[tokio::test]
340	    async fn a_dropped_relay_does_not_finish_the_last_record() {
341	        let store = ScriptedStore::new(admit);
342	        let inner = futures::stream::iter(vec![Ok(Bytes::from_static(UNTERMINATED_USAGE))]).chain(futures::stream::pending()).boxed();
343	        let mut relay = Box::pin(plain_relay(inner, Some(sent_guard(&store))));
344	        assert_eq!(relay.next().await.expect("one chunk").unwrap(), Bytes::from_static(UNTERMINATED_USAGE));
345	        assert!(store.charges().is_empty(), "nothing is charged while the stream is open");
346	        drop(relay);
347	        assert_eq!(store.charges(), vec![1], "the request estimate only");
348	    }
349	
350	    /// Review Focus 3: without a guard an unterminated tail is forwarded unchanged.
351	    #[tokio::test]
352	    async fn the_relay_forwards_an_unterminated_tail_unchanged_without_a_guard() {
353	        let chunks = vec![Ok(Bytes::from_static(b"data: a\n\n")), Ok(Bytes::from_static(UNTERMINATED_USAGE))];
354	        let out: Vec<Bytes> = plain_relay(futures::stream::iter(chunks).boxed(), None).map(|r| r.unwrap()).collect().await;
355	        assert_eq!(out.concat(), [b"data: a\n\n".as_slice(), UNTERMINATED_USAGE].concat());
356	    }
357	
358	    /// Produce a real `reqwest::Error` (there is no public constructor) by forcing a connection
359	    /// failure against an unroutable address.
360	    pub(crate) async fn make_reqwest_error() -> reqwest::Error {
361	        reqwest::Client::new()
362	            .get("http://127.0.0.1:1")
363	            .timeout(std::time::Duration::from_millis(50))
364	            .send()
365	            .await
366	            .expect_err("connection to a dead port fails")
367	    }
368	}
