315	            .snapshot()
316	            .into_vec()
317	            .into_iter()
318	            .map(|(k, _, _, v)| (k.key().name().to_owned(), k.key().labels().map(|l| (l.key().to_owned(), l.value().to_owned())).collect(), v))
319	            .collect();
320	        seen.sort_by(|a, b| a.0.cmp(&b.0));
321	        let labels = |pairs: &[(&str, &str)]| pairs.iter().map(|(k, v)| ((*k).to_owned(), (*v).to_owned())).collect::<Vec<_>>();
322	        assert_eq!(
323	            seen,
324	            vec![
325	                (
326	                    names::GATEWAY_TOOL_INTERCEPTION_DECISIONS_TOTAL.to_owned(),
327	                    labels(&[("decision", "block"), ("basis", "decider")]),
328	                    DebugValue::Counter(1)
329	                ),
