335	                    DebugValue::Counter(1)
336	                ),
337	            ]
338	        );
339	    }
340	
341	    const TERMINAL: &[u8] = b"\n\ndata: {\"error\":\"terminal\"}\n\n";
342	
343	    /// Two complete `tool_use` blocks: two holds, `Block(0)` and `Block(1)`, completed in order,
344	    /// with `gap` between the first block's end and the second block's start.
345	    fn two_tool_blocks(first: &str, second: &str, gap: Duration) -> OpenAiByteStream {
346	        let ev = |name: &str, data: String| Ok(Bytes::from(format!("event: {name}\ndata: {data}\n\n")));
347	        let block = |i: u32, name: &str| {
348	            vec![
349	                ev(
350	                    "content_block_start",
351	                    format!(r#"{{"type":"content_block_start","index":{i},"content_block":{{"type":"tool_use","id":"toolu_{i}","name":"{name}","input":{{}}}}}}"#),
352	                ),
353	                ev(
354	                    "content_block_delta",
355	                    format!(r#"{{"type":"content_block_delta","index":{i},"delta":{{"type":"input_json_delta","partial_json":"{{\"p\":{i}}}"}}}}"#),
356	                ),
357	                ev("content_block_stop", format!(r#"{{"type":"content_block_stop","index":{i}}}"#)),
358	            ]
359	        };
360	        let mut chunks = vec![ev(
361	            "message_start",
362	            r#"{"type":"message_start","message":{"id":"msg_1","type":"message","role":"assistant","content":[],"model":"claude-x","stop_reason":null}}"#.to_owned(),
363	        )];
364	        chunks.extend(block(0, first));
365	        let second_starts = chunks.len();
366	        chunks.extend(block(1, second));
367	        chunks.push(ev(
368	            "message_delta",
369	            r#"{"type":"message_delta","delta":{"stop_reason":"tool_use","stop_sequence":null},"usage":{"output_tokens":7}}"#.to_owned(),
370	        ));
371	        chunks.push(ev("message_stop", r#"{"type":"message_stop"}"#.to_owned()));
372	        futures::stream::iter(chunks.into_iter().enumerate())
373	            .then(move |(i, c)| async move {
374	                if i == second_starts {
375	                    tokio::time::sleep(gap).await;
376	                }
377	                c
378	            })
379	            .boxed()
380	    }
381	
382	    async fn run(decider: Arc<dyn ToolCallDecider>, limits: Limits, upstream: OpenAiByteStream) -> String {
383	        let ti = Arc::new(ToolInterception { limits, decider });
384	        let ctx = Arc::new(DecisionContext::new("principal", "scope", None));
385	        let turn = Arc::new(ToolTurn::Unavailable("unit test"));
386	        let out: Vec<Bytes> = relay(Format::AnthropicMessages, ti.limits, upstream, None, StreamUsage::Chat(UsageScanner::new()), ti, ctx, turn, TERMINAL)
387	            .map(|r| r.expect("infallible"))
388	            .collect()
389	            .await;
390	        String::from_utf8(out.concat()).expect("utf-8")
391	    }
392	
393	    /// Allows everything after a short wait, and records the most decisions ever in flight.
394	    #[derive(Default)]
395	    struct SlowCounting {
396	        in_flight: Arc<AtomicUsize>,
397	        max_in_flight: Arc<AtomicUsize>,
398	        calls: Arc<AtomicUsize>,
399	    }
400	
401	    impl ToolCallDecider for SlowCounting {
402	        fn decide(&self, _ctx: Arc<DecisionContext>, _turn: Arc<ToolTurn>, calls: Vec<ToolCall>) -> DecideFuture {
403	            let (in_flight, max, count) = (Arc::clone(&self.in_flight), Arc::clone(&self.max_in_flight), Arc::clone(&self.calls));
404	            Box::pin(async move {
405	                let now = in_flight.fetch_add(1, Ordering::SeqCst) + 1;
406	                max.fetch_max(now, Ordering::SeqCst);
407	                count.fetch_add(1, Ordering::SeqCst);
408	                tokio::time::sleep(Duration::from_millis(30)).await;
409	                in_flight.fetch_sub(1, Ordering::SeqCst);
410	                Ok(vec![Decision::Allow; calls.len()])
411	            })
412	        }
413	    }
414	
415	    /// Never answers for a call named `hang_*`; allows everything else at once.
416	    struct HangNamed;
417	
418	    impl ToolCallDecider for HangNamed {
419	        fn decide(&self, _ctx: Arc<DecisionContext>, _turn: Arc<ToolTurn>, calls: Vec<ToolCall>) -> DecideFuture {
420	            if calls.iter().any(|c| c.name.starts_with("hang_")) {
421	                return Box::pin(std::future::pending());
422	            }
423	            Box::pin(std::future::ready(Ok(vec![Decision::Allow; calls.len()])))
424	        }
425	    }
426	
427	    /// SMA-730 R1 with interception on: a transport error after an unterminated usage record runs
428	    /// `finish_scan` before `abort()`, so the reported total is charged, and the core's terminal
429	    /// frame is the only one.
430	    #[tokio::test]
431	    async fn a_transport_error_after_an_unterminated_usage_record_charges_the_reported_tokens() {
432	        use crate::adapters::http::chat::TERMINAL_SSE_ERROR;
433	        use crate::adapters::http::chat::tests::{UNTERMINATED_USAGE, admit, make_reqwest_error, sent_guard};
434	        use crate::test_support::ScriptedStore;
435	        let store = ScriptedStore::new(admit);
436	        let upstream = futures::stream::iter(vec![Ok(Bytes::from_static(UNTERMINATED_USAGE))])
437	            .chain(futures::stream::once(async { Err(make_reqwest_error().await) }))
438	            .boxed();
439	        let ti = Arc::new(ToolInterception {
440	            limits: Limits::defaults(),
441	            decider: Arc::new(paigasus_gateway_core::AllowAll),
442	        });
443	        let ctx = Arc::new(DecisionContext::new("principal", "scope", None));
444	        let turn = Arc::new(ToolTurn::Unavailable("unit test"));
445	        let out: Vec<Bytes> = intercepted_stream(
446	            Format::OpenAiChat,
447	            ti.limits,
448	            upstream,
449	            Some(sent_guard(&store)),
450	            StreamUsage::Chat(UsageScanner::new()),
451	            ti,
452	            ctx,
453	            turn,
454	            TERMINAL_SSE_ERROR.as_bytes(),
455	        )
456	        .map(|r| r.expect("infallible"))
457	        .collect()
458	        .await;
459	        let text = String::from_utf8(out.concat()).expect("utf-8");
460	        assert_eq!(text.matches(TERMINAL_SSE_ERROR.trim()).count(), 1, "{text}");
461	        assert_eq!(store.charges(), vec![7]);
462	    }
463	
464	    /// P-5: two holds, decided one after the other, never both at once.
465	    #[tokio::test]
466	    async fn the_decider_runs_one_hold_at_a_time() {
467	        let decider = Arc::new(SlowCounting::default());
468	        let text = run(decider.clone(), Limits::defaults(), two_tool_blocks("read_file", "list_dir", Duration::ZERO)).await;
469	        assert!(text.contains(r#""decision":"allow","basis":"decider""#), "{text}");
470	        assert_eq!(decider.calls.load(Ordering::SeqCst), 2);
471	        assert_eq!(decider.max_in_flight.load(Ordering::SeqCst), 1);
472	    }
473	
474	    /// When a timeout rules on the hold being decided, its future is dropped and the next
475	    /// hold is decided. The second hold completes 600 ms after the first, so its own deadline
476	    /// (1.6 s) lies 600 ms after the first one's (1 s): kept, the stale future would hold it until
477	    /// that deadline and it would be blocked too. Wide margins, for a loaded CI runner.
478	    #[tokio::test]
479	    async fn a_timed_out_decision_does_not_block_the_next_hold() {
480	        let limits = Limits {
481	            decide_timeout: Duration::from_secs(1),
482	            ..Limits::defaults()
483	        };
484	        let text = tokio::time::timeout(
485	            Duration::from_secs(5),
486	            run(Arc::new(HangNamed), limits, two_tool_blocks("hang_x", "read_file", Duration::from_millis(600))),
487	        )
488	        .await
489	        .expect("the stream ends");
490	        assert!(
491	            text.contains(r#""name":"hang_x","name_sha256_8""#) && text.contains(&format!(r#""code":"{}""#, BlockCode::DeciderError.as_kebab())),
492	            "{text}"
493	        );
494	        assert!(text.contains(r#""name":"read_file","name_sha256_8""#), "{text}");
495	        let read_file_report = text
496	            .lines()
497	            .find(|l| l.contains(r#""name":"read_file""#) && l.starts_with(": paigasus-decision"))
498	            .expect("a report for read_file");
499	        assert!(read_file_report.contains(r#""decision":"allow","basis":"decider""#), "{read_file_report}");
500	        assert!(text.contains(r#""name":"read_file","input":{}"#), "the allowed call is forwarded: {text}");
501	    }
