3	//! axum HTTP surface: `/healthz` (liveness, no dependency checks) and `/readyz` (a real
4	//! readiness probe — IAM reachability via a sentinel introspect; the upstream is validated by
5	//! config-presence at boot) stay public; the protected `/v1/chat/completions` proxy ([`chat`]) is
6	//! fronted by the auth middleware ([`auth`]) plus a request-body size limit and renders failures
7	//! through the OpenAI-compatible error envelope ([`error`]). The inbound chat-completion request
8	//! DTO ([`dto`]) is parsed only to read `model`/`stream`. `GET /v1/service-info` ([`service_info`],
9	//! SMA-505) is a THIRD, separately-protected group: it authenticates via [`auth::require_authenticated`]
10	//! but never authorizes, and carries no body limit.
11	
12	pub mod auth;
13	pub(crate) mod bytes;
14	pub mod chat;
15	pub mod dto;
