38	/// Deliberately-INVALID sentinel token for the `/readyz` IAM-reachability probe. It has no
39	/// `pgs_sk_` prefix, so a REACHABLE IAM parses and rejects it (an application-level `Status`, e.g.
40	/// `Unauthenticated`) while an UNREACHABLE IAM fails at the transport. It authenticates nothing —
41	/// the introspect is a cheap, unaudited parse-reject, never a real credential.
42	const READYZ_PROBE_TOKEN: &str = "readyz-probe";
43	
44	/// Shared handler state: the IAM port (an `Arc<dyn Iam>` so tests inject a fake and the binary
45	/// injects the real `IamClient`), the OpenAI egress client, and the inbound body-size cap. `Clone`
46	/// is cheap (all fields are `Arc`/`Copy`), as axum requires for `State`.
47	#[derive(Clone)]
48	pub struct AppState {
49	    /// The IAM port the auth middleware queries (introspect + self-query authorize).
50	    pub iam: Arc<dyn Iam>,
51	    /// The outbound OpenAI egress client (holds the real key; forwards raw request bytes).
52	    pub openai: Arc<OpenAiClient>,
53	    /// Max inbound request-body size in bytes; an over-limit body is rejected by [`bytes::EnvelopeBytes`]
54	    /// with a `413` rendered inside the OpenAI envelope (SMA-588).
55	    pub max_request_bytes: usize,
56	    /// The capability toggles this build was configured with (SMA-505), projected once via
57	    /// `Capabilities::from_config` in `main.rs` (mirrors `paigasus-iam`'s `AppState.capabilities`
58	    /// — one source of truth, read by both the `chat` streaming guard and the `service_info`
59	    /// descriptor handler, rather than each holding/re-deriving its own bare bool).
60	    pub capabilities: crate::service_info::Capabilities,
61	    /// SMA-677: the rate limit and token budget, or `None` when `[limits]` is absent — then the
62	    /// handler skips them entirely and behaves exactly as before (A6).
63	    pub limits: Option<Arc<Limits>>,
64	    /// SMA-700: `GatewayConfig::dpop.enabled`. The auth middlewares read it through `AuthState`.
65	    pub dpop_enabled: bool,
66	    /// SMA-749: tool-call interception, or `None` when `[tool_interception] enabled = false`.
67	    /// `None` keeps the relay exactly as it was (D27).
68	    pub tool_interception: Option<Arc<interception::ToolInterception>>,
69	    /// SMA-769: the `POST /v1/responses` route, or `None` when `[responses] enabled = false`
70	    /// (D8). A later task mounts the route only when this is `Some`.
71	    pub responses: Option<Arc<ResponsesSettings>>,
72	}
73	
74	/// SMA-769 D15: the limits of the Responses route, built from `[responses]` when it is on.
75	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
76	pub struct ResponsesSettings {
77	    /// The cap on one request body of the route.
78	    pub max_request_bytes: usize,
79	    /// One SSE record larger than this is a failure.
80	    pub max_record_bytes: usize,
81	    /// The queued bytes of one stream; also the cap on one non-stream body.
82	    pub max_held_bytes: usize,
83	}
84	
85	/// The gateway's HTTP surface. `/healthz` + `/readyz` are public (no auth, no body limit); the
86	/// `/v1/chat/completions` proxy is protected by the G5 auth middleware and a
87	/// [`DefaultBodyLimit`] cap; `GET /v1/service-info` (SMA-505) is protected by
88	/// [`require_authenticated`] alone, in its OWN `route_layer` group. Each protected group's
89	/// middleware is applied via [`Router::route_layer`], which runs the layers ONLY for the matched
90	/// route in THAT group — so the health probes stay outside auth AND the body limit, the
91	/// descriptor never inherits the chat group's authorization check or body limit, and an
92	/// unmatched path still 404s without first being challenged for a credential.
93	///
94	/// The discovery route deliberately does NOT join `protected`: `require_iam_auth` runs a D9
95	/// self-query authorization on top of authentication, and discovery must authenticate but never
96	/// authorize (a caller who legitimately cannot invoke the model must still be able to learn that
97	/// streaming exists). It also needs no [`DefaultBodyLimit`] — it is a GET with no body. Merging
98	/// it into `protected` would silently saddle it with both.
99	///
100	/// The shared [`AppState`] is applied ONCE, at the end, over the whole tree so the stateful
101	/// `readyz` (it probes IAM), the protected chat handler, and the descriptor handler all read the
102	/// same state. `healthz` takes no state — a stateless handler is still valid inside a stateful
103	/// router.
104	///
105	/// [`paigasus_observability::http_metrics_layer`] is applied over the whole tree (health routes
106	/// included — they get a bounded `route` label, which is acceptable). `/metrics` itself is
107	/// deliberately NOT part of this router: it is merged in by `main` (or served on its own
108	/// listener) AFTER this function returns, so a scrape never inflates its own request metrics.
109	pub fn router(state: AppState) -> Router {
110	    // The auth middlewares' state is the IAM port and the DPoP switch (`AuthState`), captured here
111	    // BEFORE the final `with_state`, and independent of the handler's `AppState`.
112	    let auth_state = AuthState {
113	        iam: state.iam.clone(),
114	        dpop_enabled: state.dpop_enabled,
115	    };
116	    let auth = axum::middleware::from_fn_with_state(auth_state.clone(), require_iam_auth);
117	    // The body-size limit: an over-limit body fails the handler's `EnvelopeBytes` extractor with
118	    // a `413` rendered inside the OpenAI envelope (SMA-588), not axum's plain text.
119	    // Note (M0): auth runs BEFORE the 413 (the limit is enforced at body extraction, after the
120	    // middleware) — acceptable here since auth reads only headers, never the body.
121	    let body_limit = DefaultBodyLimit::max(state.max_request_bytes);
122	
123	    let protected = Router::new().route("/v1/chat/completions", post(chat::chat_completions)).route_layer(auth).route_layer(body_limit);
124	
125	    // SMA-505: its own group, because discovery authenticates but does not authorize, and needs
126	    // no body limit (it is a GET). `route_layer` keeps the middleware off unmatched paths, so a
127	    // 404 is still a 404 rather than a credential challenge.
128	    let discovery_auth = axum::middleware::from_fn_with_state(auth_state, require_authenticated);
129	    let discovery = Router::new().route(paigasus_service_info::ROUTE, get(service_info::get_service_info)).route_layer(discovery_auth);
130	
131	    Router::new()
132	        .route("/healthz", get(healthz))
133	        .route("/readyz", get(readyz))
134	        .merge(protected)
135	        .merge(discovery)
136	        .layer(paigasus_observability::http_metrics_layer("gateway"))
137	        // SMA-504 D10: mirrors IAM's placement exactly — outermost, so an auth rejection is
138	        // attributable. Note this router DOES include /healthz and /readyz (unlike IAM's, which
139	        // merges them above `app_routes`), so they carry ids here; harmless and not worth
140	        // diverging the two services' composition for.
141	        .layer(paigasus_observability::CorrelationLayer)
142	        .with_state(state)
143	}
144	
145	async fn healthz() -> impl IntoResponse {
146	    (StatusCode::OK, Json(json!({ "status": "ok" })))
147	}
148	
149	/// Readiness probe: `200 {"status":"ready"}` only when the gateway can actually serve. For M0 the
150	/// meaningful hard dependency is IAM (every request introspects + authorizes against it), so
151	/// readiness turns on IAM reachability; a transient upstream blip must NOT flap readiness, so the
152	/// OpenAI upstream is checked by config-presence only (see below), never a per-poll network probe.
153	///
154	/// ## IAM reachability via a sentinel introspect (a dedicated gRPC health RPC is a follow-up)
155	/// The M0 [`Iam`] port exposes no health RPC, so reachability is inferred from a cheap sentinel
156	/// `IntrospectApiKey` with the deliberately-invalid [`READYZ_PROBE_TOKEN`]: a REACHABLE IAM parses
157	/// and rejects it, returning an application-level `Status` (e.g. `Unauthenticated`); an UNREACHABLE
158	/// IAM fails at the transport ([`IamError::Connect`], or an `Rpc` `Status` of
159	/// `Unavailable`/`DeadlineExceeded`/`Internal`). The probe is a plain parse-reject — cheap and NOT
160	/// audited (it authenticates nothing). A dedicated IAM gRPC health RPC is the documented follow-up.
161	///
162	/// Classification: transport/backend outcomes (`Connect` / `Unavailable` / `DeadlineExceeded` /
163	/// `Internal`) → NOT ready (`503`) — kept consistent with `auth::introspect_error`'s request-path
164	/// mapping so the probe reports not-ready during the same IAM failures that break real requests;
165	/// ANY other outcome (an application-level `Status` such as `Unauthenticated`, or even an `Ok`)
166	/// proves IAM answered → ready (`200`).
167	///
168	/// ## Upstream — config-presence only for M0 (a live probe is a follow-up)
169	/// `upstream.openai.{base_url,api_key}` are validated non-empty at boot by
170	/// `GatewayConfig::validate`, so there is nothing further to check here without a live network
171	/// probe on every poll (flaky + rate-costly). A live upstream-reachability probe is a documented
172	/// follow-up; deliberately NOT added here.
173	async fn readyz(State(state): State<AppState>) -> Response {
174	    match state.iam.introspect_api_key(READYZ_PROBE_TOKEN).await {
175	        // Transport/backend failures → IAM unreachable or unhealthy → not ready. `Internal` is
176	        // included so this stays consistent with `auth::introspect_error`, which maps `Internal` to
177	        // `IamUnavailable` (503) on the request path: a persistent `Internal` from IAM would
178	        // otherwise make `/readyz` report ready while every real chat request fails 503 — exactly
179	        // the outage the probe exists to catch.
180	        Err(IamError::Connect(_)) => iam_not_ready(),
181	        Err(IamError::Rpc(status)) if matches!(status.code(), tonic::Code::Unavailable | tonic::Code::DeadlineExceeded | tonic::Code::Internal) => iam_not_ready(),
182	        // Any other application-level `Status` (e.g. `Unauthenticated`) or an `Ok` proves IAM answered.
183	        Err(IamError::Rpc(_)) | Ok(_) => (StatusCode::OK, Json(json!({ "status": "ready" }))).into_response(),
184	    }
185	}
186	
187	/// The `503` readiness response when the IAM dependency is unreachable. Static, dependency-scoped,
188	/// and carries no upstream detail.
189	fn iam_not_ready() -> Response {
190	    (StatusCode::SERVICE_UNAVAILABLE, Json(json!({ "status": "not_ready", "dependency": "iam" }))).into_response()
191	}
