194	mod tests {
195	    use super::*;
196	    use crate::adapters::iam::{CallerCredential, DpopContext};
197	    use crate::config::OpenAiConfig;
198	    use axum::body::Body;
199	    use axum::http::Request;
200	    use paigasus_proto::paigasus::iam::v1::IntrospectApiKeyResponse;
201	    use secrecy::SecretString;
202	    use std::time::Duration;
203	    use tonic::Status;
204	    use tower::ServiceExt; // for `oneshot`
205	
206	    /// A never-invoked `Iam` for the routes that must NOT touch IAM (`/healthz`, and the unauth
207	    /// `/v1/chat/completions` row that 401s before any IAM call). Its methods panic, so a test
208	    /// using it that DID reach IAM would fail loudly — which is exactly how `/healthz` proves it
209	    /// has no IAM dependency. The full auth-path table lives in G5's `auth.rs` unit tests and G7's
210	    /// `tests/chat_proxy.rs`.
211	    struct UnusedIam;
212	
213	    #[async_trait::async_trait]
214	    impl Iam for UnusedIam {
215	        async fn introspect_api_key(&self, _token: &str) -> Result<IntrospectApiKeyResponse, IamError> {
216	            unreachable!("this route must never call IAM")
217	        }
218	        async fn is_authorized_self(&self, _caller: &CallerCredential, _principal_prn: &str, _action: &str, _resource_prn: &str) -> Result<bool, IamError> {
219	            unreachable!("this route must never call IAM")
220	        }
221	        async fn introspect_token(&self, _token: &str, _dpop: Option<DpopContext>) -> Result<paigasus_proto::paigasus::iam::v1::IntrospectResponse, IamError> {
222	            unreachable!("this route must never call IAM")
223	        }
224	    }
225	
226	    /// The introspect outcome a [`ProbeIam`] returns for the `/readyz` sentinel probe — either a
227	    /// REACHABLE IAM (it answered: an `Ok`, or an application-level `Unauthenticated`) or an
228	    /// UNREACHABLE/UNHEALTHY one (a transport/backend `Unavailable`/`DeadlineExceeded`/`Internal`
229	    /// `Rpc`, or `Connect`).
230	    #[derive(Clone, Copy)]
231	    enum Probe {
232	        ReachableOk,
233	        ReachableUnauthenticated,
234	        UnreachableUnavailable,
235	        UnreachableDeadline,
236	        UnreachableInternal,
237	        UnreachableConnect,
238	    }
239	
240	    /// A configurable `Iam` for the readiness tests: `introspect_api_key` yields the selected
241	    /// [`Probe`] outcome so `/readyz`'s reachable/unreachable classification is exercised.
242	    struct ProbeIam(Probe);
243	
244	    #[async_trait::async_trait]
245	    impl Iam for ProbeIam {
246	        async fn introspect_api_key(&self, _token: &str) -> Result<IntrospectApiKeyResponse, IamError> {
247	            match self.0 {
248	                Probe::ReachableOk => Ok(IntrospectApiKeyResponse::default()),
249	                Probe::ReachableUnauthenticated => Err(IamError::Rpc(Status::unauthenticated("invalid key"))),
250	                Probe::UnreachableUnavailable => Err(IamError::Rpc(Status::unavailable("iam is down"))),
251	                Probe::UnreachableDeadline => Err(IamError::Rpc(Status::deadline_exceeded("iam timed out"))),
252	                Probe::UnreachableInternal => Err(IamError::Rpc(Status::internal("iam internal error"))),
253	                Probe::UnreachableConnect => Err(IamError::Connect("channel build failed".to_string())),
254	            }
255	        }
256	        async fn is_authorized_self(&self, _caller: &CallerCredential, _principal_prn: &str, _action: &str, _resource_prn: &str) -> Result<bool, IamError> {
257	            unreachable!("the readiness probe never authorizes")
258	        }
259	        async fn introspect_token(&self, _token: &str, _dpop: Option<DpopContext>) -> Result<paigasus_proto::paigasus::iam::v1::IntrospectResponse, IamError> {
260	            unreachable!("the readiness probe never introspects a token")
261	        }
262	    }
263	
264	    /// An OpenAI client that points nowhere in particular — the health/readiness routes never call
265	    /// the upstream, so it is only there to satisfy [`AppState`].
266	    fn unused_openai() -> OpenAiClient {
267	        let cfg = OpenAiConfig {
268	            base_url: "http://127.0.0.1:1".to_string(),
269	            api_key: SecretString::from("sk-unused".to_string()),
270	            extra_ca_bundle_path: None,
271	        };
272	        OpenAiClient::new(&cfg, Duration::from_secs(1), Duration::from_secs(1), Duration::from_secs(1)).expect("client builds")
273	    }
274	
275	    /// A test `AppState` over the given IAM port (the OpenAI client is never called by these routes).
276	    fn state_with_iam(iam: Arc<dyn Iam>) -> AppState {
277	        AppState {
278	            iam,
279	            openai: Arc::new(unused_openai()),
280	            max_request_bytes: 1_048_576,
281	            capabilities: crate::service_info::Capabilities { chat_stream: true },
282	            limits: None,
283	            dpop_enabled: false,
284	            tool_interception: None,
285	            responses: None,
286	        }
287	    }
288	
289	    async fn get_status(app: Router, uri: &str) -> StatusCode {
290	        app.oneshot(Request::builder().uri(uri).body(Body::empty()).unwrap()).await.unwrap().status()
291	    }
292	
293	    #[tokio::test]
294	    async fn healthz_returns_200_with_status_ok_body_and_no_iam_dependency() {
295	        // `UnusedIam` panics if called — so a 200 here also proves `/healthz` never touches IAM.
296	        let app = router(state_with_iam(Arc::new(UnusedIam)));
297	        let resp = app.oneshot(Request::builder().uri("/healthz").body(Body::empty()).unwrap()).await.unwrap();
298	        assert_eq!(resp.status(), StatusCode::OK);
299	        let body = axum::body::to_bytes(resp.into_body(), usize::MAX).await.unwrap();
300	        let json: serde_json::Value = serde_json::from_slice(&body).unwrap();
301	        assert_eq!(json, json!({ "status": "ok" }));
302	    }
303	
304	    #[tokio::test]
305	    async fn healthz_stays_200_even_when_iam_is_unreachable() {
306	        // Liveness must not flap on a dependency outage: `/healthz` is 200 regardless of IAM.
307	        let app = router(state_with_iam(Arc::new(ProbeIam(Probe::UnreachableUnavailable))));
308	        assert_eq!(get_status(app, "/healthz").await, StatusCode::OK);
309	    }
310	
311	    #[tokio::test]
312	    async fn readyz_is_200_when_iam_is_reachable() {
313	        // Both a reachable-Ok and a reachable-but-rejecting (`Unauthenticated`) IAM prove IAM
314	        // answered → ready.
315	        for probe in [Probe::ReachableOk, Probe::ReachableUnauthenticated] {
316	            let app = router(state_with_iam(Arc::new(ProbeIam(probe))));
317	            assert_eq!(get_status(app, "/readyz").await, StatusCode::OK, "reachable IAM must be ready");
318	        }
319	    }
320	
321	    #[tokio::test]
322	    async fn readyz_is_503_when_iam_is_unreachable() {
323	        // A transport/backend outcome (Connect, or an Unavailable/DeadlineExceeded/Internal Rpc) →
324	        // not ready. `Internal` is included to match `introspect_error`'s request-path mapping.
325	        for probe in [Probe::UnreachableUnavailable, Probe::UnreachableDeadline, Probe::UnreachableInternal, Probe::UnreachableConnect] {
326	            let app = router(state_with_iam(Arc::new(ProbeIam(probe))));
327	            assert_eq!(get_status(app, "/readyz").await, StatusCode::SERVICE_UNAVAILABLE, "unreachable IAM must be not-ready");
328	        }
329	    }
330	
331	    #[tokio::test]
332	    async fn chat_route_requires_auth_missing_bearer_is_401() {
333	        // The protected route is behind the auth middleware; with no bearer it 401s before any
334	        // IAM/upstream call (proves the layer is wired, without needing a live upstream). `UnusedIam`
335	        // panics if reached, so the 401 also proves no IAM call happens on the missing-bearer path.
336	        let app = router(state_with_iam(Arc::new(UnusedIam)));
337	        let req = Request::builder().method("POST").uri("/v1/chat/completions").body(Body::from("{}")).unwrap();
338	        let resp = app.oneshot(req).await.unwrap();
339	        assert_eq!(resp.status(), StatusCode::UNAUTHORIZED);
340	    }
341	
342	    /// SMA-504 D10: the correlation layer attaches where `http_metrics_layer` attaches, so every
343	    /// API response carries both ids — including a 401 from the auth middleware.
344	    #[tokio::test]
345	    async fn every_api_response_carries_both_ids() {
346	        // `UnusedIam` panics if reached — the missing-bearer 401 rejects before any IAM call, so
347	        // this also proves the correlation layer sits OUTSIDE the auth middleware (not inside it).
348	        let app = router(state_with_iam(Arc::new(UnusedIam)));
349	        // No credential: `require_iam_auth` rejects at the middleware, before any handler.
350	        let resp = app
351	            .oneshot(axum::http::Request::builder().method("POST").uri("/v1/chat/completions").body(axum::body::Body::empty()).unwrap())
352	            .await
353	            .unwrap();
354	        assert_eq!(resp.status(), axum::http::StatusCode::UNAUTHORIZED);
355	        assert!(resp.headers().contains_key("paigasus-request-id"));
356	        assert!(resp.headers().contains_key("paigasus-correlation-id"));
357	        assert_eq!(resp.headers()["paigasus-retryable"], "false", "a 401 is not retryable");
358	    }
359	
360	    /// SMA-504 D10 amendment (final whole-branch review, finding #4): unlike IAM, the gateway's
361	    /// `/healthz` and `/readyz` sit INSIDE `CorrelationLayer` and DO carry both ids — the router
362	    /// is flatter than IAM's (no pre-layer health/readyz split to carve them out of), and
363	    /// `/readyz` already does a real IAM RPC every poll, so two more UUIDv7 mints cost nothing
364	    /// extra. Pinned so this narrowing is a decision, not an accident a later reader "fixes" to
365	    /// match IAM's opposite choice.
366	    #[tokio::test]
367	    async fn healthz_and_readyz_carry_ids_too() {
368	        let app = router(state_with_iam(Arc::new(ProbeIam(Probe::ReachableOk))));
369	
370	        let resp = app.clone().oneshot(Request::builder().uri("/healthz").body(Body::empty()).unwrap()).await.unwrap();
371	        assert_eq!(resp.status(), StatusCode::OK);
372	        assert!(resp.headers().contains_key("paigasus-request-id"), "the gateway's /healthz carries ids, unlike IAM's");
373	        assert!(resp.headers().contains_key("paigasus-correlation-id"));
374	
375	        let resp = app.oneshot(Request::builder().uri("/readyz").body(Body::empty()).unwrap()).await.unwrap();
376	        assert_eq!(resp.status(), StatusCode::OK);
377	        assert!(resp.headers().contains_key("paigasus-request-id"), "the gateway's /readyz carries ids, unlike IAM's");
378	        assert!(resp.headers().contains_key("paigasus-correlation-id"));
379	    }
380	}
