1	// SPDX-License-Identifier: Apache-2.0
2	//! SMA-749: drives `paigasus-gateway-core` inside the chat relay (spec § 5.2).
3	//!
4	//! The interceptor is synchronous; this module owns the I/O around it: the upstream stream, one
5	//! pending decider future, and one timer. Nothing is spawned. Dropping the response body drops
6	//! the unfold state, and with it the upstream request (cancel-on-drop, D25) and any pending
7	//! decision.
8	//!
9	//! Like the plain relay, this runs with `current_ids() == None` (SMA-504 § 4.3): the request id
10	//! reaches the decider through `DecisionContext`, captured in the handler.
11	//!
12	//! The decider future and the timer are driven only while the client polls the body, so a client
13	//! that stalls long enough can see a hold end as `decider-error` (or `on_failure` in observe mode).
14	//!
15	//! On a client disconnect mid-hold, billing follows what the relay had read from the upstream so
16	//! far, read-ahead included, exactly as in the plain relay (SMA-730 D3).
17	
18	use std::collections::VecDeque;
19	use std::convert::Infallible;
20	use std::pin::Pin;
21	use std::sync::Arc;
22	use std::time::Instant;
23	
24	use axum::body::Bytes;
25	use futures::{Stream, StreamExt};
26	use metrics::{counter, histogram};
27	use paigasus_gateway_core::{
28	    Action, Basis, BlockCode, DecideFuture, DeciderError, Decision, DecisionContext, Format, HoldKey, Interceptor, Limits, Metric, OnFailure, ToolCall, ToolCallDecider, ToolTurn, parse_body,
29	};
30	use paigasus_observability::names;
31	
32	use crate::adapters::http::chat::{feed_scan, finish_scan};
33	use crate::adapters::http::usage::StreamUsage;
34	use crate::adapters::openai::OpenAiByteStream;
35	use crate::application::charge_guard::ChargeGuard;
36	
37	/// What `[tool_interception]` builds at boot.
38	pub struct ToolInterception {
39	    pub limits: Limits,
40	    pub decider: Arc<dyn ToolCallDecider>,
41	}
42	
43	/// Map one core metric to the registered names (P-9).
44	pub(crate) fn record(m: Metric) {
45	    match m {
46	        Metric::RecordDropped(reason) => counter!(names::GATEWAY_TOOL_INTERCEPTION_RECORDS_DROPPED_TOTAL, "reason" => reason).increment(1),
47	        Metric::Decision { decision, basis } => counter!(names::GATEWAY_TOOL_INTERCEPTION_DECISIONS_TOTAL, "decision" => decision, "basis" => basis).increment(1),
48	        Metric::OnFailure(code) => counter!(names::GATEWAY_TOOL_INTERCEPTION_ON_FAILURE_TOTAL, "code" => code).increment(1),
49	        Metric::HoldSeconds(s) => histogram!(names::GATEWAY_TOOL_INTERCEPTION_HOLD_SECONDS).record(s),
50	    }
51	}
52	
53	/// What the non-stream path does with a body (spec § 5.2).
54	pub(crate) enum BodyOutcome {
55	    /// `rewritten` is `None` when the caller forwards the original body it still owns.
56	    Forward { rewritten: Option<Bytes>, report: Option<String> },
57	    /// D16 block on a body that cannot be checked: the 502 `tool-interception-malformed-response`.
58	    Refuse,
59	}
60	
61	/// Parse, decide and rewrite one complete 2xx body. The usage read happened on the ORIGINAL body
62	/// before this runs (D24), so nothing here changes the charge.
63	pub(crate) async fn intercept_body(ti: &ToolInterception, limits: Limits, format: Format, ctx: Arc<DecisionContext>, turn: Arc<ToolTurn>, body: &[u8]) -> BodyOutcome {
64	    // The body cap is `max_held_bytes` (spec § 5.2).
65	    let calls = match parse_body(format, body, limits.max_held_bytes) {
66	        Ok(c) => c,
67	        Err(_) => {
68	            record(Metric::OnFailure("malformed"));
69	            return match limits.on_failure {
70	                OnFailure::Block => BodyOutcome::Refuse,
71	                OnFailure::Allow => BodyOutcome::Forward { rewritten: None, report: None },
72	            };
73	        }
74	    };
75	    if calls.calls.is_empty() && calls.unenforceable.is_empty() {
76	        return BodyOutcome::Forward { rewritten: None, report: None };
77	    }
78	    let n = calls.calls.len();
79	    let (decisions, basis) = if n == 0 {
80	        (Vec::new(), Basis::Decider)
81	    } else {
82	        let fut = ti.decider.decide(ctx, turn, calls.calls.clone());
83	        match tokio::time::timeout(limits.decide_timeout, fut).await {
84	            Ok(Ok(d)) if d.len() == n => (d, Basis::Decider),
85	            _ => {
86	                record(Metric::OnFailure("decider_error"));
87	                match limits.on_failure {
88	                    OnFailure::Block => (vec![Decision::Block { code: BlockCode::DeciderError }; n], Basis::OnFailure),
89	                    OnFailure::Allow => (vec![Decision::Allow; n], Basis::OnFailure),
90	                }
91	            }
92	        }
93	    };
94	    for d in &decisions {
95	        let decision = if d.is_allow() { "allow" } else { "block" };
96	        record(Metric::Decision { decision, basis: basis.as_str() });
97	    }
98	    let report = calls.report(&decisions, basis);
99	    let rewritten = calls.apply(&decisions).map(Bytes::from);
100	    BodyOutcome::Forward { rewritten, report: Some(report) }
101	}
102	
103	/// The unfold state. It owns the upstream, the charge guard and the pending decision, so a
104	/// client disconnect drops all three (D25), exactly as the plain relay drops the first two.
105	struct Relay {
106	    /// `None` once the upstream has ended, failed, or been drained.
107	    inner: Option<OpenAiByteStream>,
108	    scan: StreamUsage,
109	    guard: Option<ChargeGuard>,
110	    icpt: Interceptor,
111	    ti: Arc<ToolInterception>,
112	    ctx: Arc<DecisionContext>,
113	    turn: Arc<ToolTurn>,
114	    out: VecDeque<Bytes>,
115	    /// Completed holds waiting for the decider, in completion order (P-5).
116	    decide_queue: VecDeque<(HoldKey, Vec<ToolCall>)>,
117	    /// The one decision in flight (P-5).
118	    pending: Option<(HoldKey, DecideFuture)>,
119	    sleep: Pin<Box<tokio::time::Sleep>>,
120	}
121	
122	/// What woke the relay.
123	enum Event {
124	    Decided(Result<Vec<Decision>, DeciderError>),
125	    Wake,
126	    Upstream(Option<Result<Bytes, reqwest::Error>>),
127	}
128	
129	impl Relay {
130	    fn apply(&mut self, actions: Vec<Action>) {
131	        for a in actions {
132	            match a {
133	                Action::Emit(b) => self.out.push_back(b),
134	                Action::Decide { hold, calls } => self.decide_queue.push_back((hold, calls)),
135	                // The core never returns a wake in the past, so this cannot spin.
136	                Action::Wake(at) => self.sleep.as_mut().reset(tokio::time::Instant::from_std(at)),
137	                Action::Count(m) => record(m),
138	            }
139	        }
140	        // A hold that is no longer deciding (a timeout ruled on it) needs no answer. Drop
141	        // its future so the next hold is not stuck behind it.
142	        if let Some((hold, _)) = &self.pending
143	            && !self.icpt.is_deciding(*hold)
144	        {
145	            self.pending = None;
146	        }
147	    }
148	
149	    /// Start the next decision if none is in flight. Holds ruled on while they queued are skipped.
150	    fn start_next_decision(&mut self) {
151	        while self.pending.is_none() {
152	            let Some((hold, calls)) = self.decide_queue.pop_front() else { return };
153	            if self.icpt.is_deciding(hold) {
154	                let fut = self.ti.decider.decide(Arc::clone(&self.ctx), Arc::clone(&self.turn), calls);
155	                self.pending = Some((hold, fut));
156	            }
157	        }
158	    }
159	
160	    /// Biased in the spec's order (§ 5.2): decider, timer, upstream.
161	    async fn next_event(&mut self) -> Event {
162	        let Relay { inner, pending, sleep, .. } = self;
163	        tokio::select! {
164	            biased;
165	            r = async {
166	                match pending.as_mut() {
167	                    Some((_, f)) => f.as_mut().await,
168	                    None => std::future::pending().await,
169	                }
170	            } => Event::Decided(r),
171	            () = sleep.as_mut() => Event::Wake,
172	            c = async {
173	                match inner.as_mut() {
174	                    Some(s) => s.next().await,
175	                    None => std::future::pending().await,
176	                }
177	            } => Event::Upstream(c),
178	        }
179	    }
180	
181	    /// The interceptor ended the client stream (an upstream error record mid-hold) while the
182	    /// upstream is still open. Today's relay would read the upstream to its end, so with a guard
183	    /// the rest is read for billing only (the usage record usually follows), and the charge stays
184	    /// what it is with interception off (D24). Without a guard there is nothing to bill, and the
185	    /// upstream is dropped at once.
186	    async fn drain_for_billing(&mut self) {
187	        let Some(mut inner) = self.inner.take() else { return };
188	        if self.guard.is_some() {
189	            while let Some(Ok(chunk)) = inner.next().await {
190	                feed_scan(&mut self.scan, &mut self.guard, &chunk);
191	            }
192	        }
193	        finish_scan(&mut self.scan, &mut self.guard);
194	    }
195	}
196	
197	/// The streaming relay with interception on (spec § 5.2, D17, D24, D25).
198	///
199	/// 1. Each upstream chunk goes to the usage scanner first, exactly as in the plain relay, and
200	///    then to [`Interceptor::push`].
201	/// 2. On the first upstream `Err`: `finish_scan`, then [`Interceptor::abort`], which emits the
202	///    terminal frame. The relay does not emit it a second time.
203	/// 3. On the upstream end: `finish_scan`, then [`Interceptor::finish`].
204	/// 4. Decisions run one at a time (P-5).
205	/// 5. Nothing is spawned.
206	#[allow(clippy::too_many_arguments)]
207	pub(crate) fn intercepted_stream(
208	    format: Format,
209	    limits: Limits,
210	    inner: OpenAiByteStream,
211	    guard: Option<ChargeGuard>,
212	    usage: StreamUsage,
213	    ti: Arc<ToolInterception>,
214	    ctx: Arc<DecisionContext>,
215	    turn: Arc<ToolTurn>,
216	    terminal: &'static [u8],
217	) -> impl Stream<Item = Result<Bytes, Infallible>> + Send + 'static {
218	    relay(format, limits, inner, guard, usage, ti, ctx, turn, terminal)
219	}
220	
221	/// [`intercepted_stream`] for any wire format. The unit tests drive an Anthropic stream through
222	/// it, because only that format has more than one hold per stream (an OpenAI chat stream
223	/// carries tool calls in choice 0 only), and P-5 and the dropped stale decision are about the
224	/// second hold.
225	#[allow(clippy::too_many_arguments)]
226	fn relay(
227	    format: Format,
228	    limits: Limits,
229	    inner: OpenAiByteStream,
230	    guard: Option<ChargeGuard>,
231	    usage: StreamUsage,
232	    ti: Arc<ToolInterception>,
233	    ctx: Arc<DecisionContext>,
234	    turn: Arc<ToolTurn>,
235	    terminal: &'static [u8],
236	) -> impl Stream<Item = Result<Bytes, Infallible>> + Send + 'static {
237	    let now = Instant::now();
238	    let icpt = Interceptor::new(format, limits, Bytes::from_static(terminal), now);
239	    let sleep = Box::pin(tokio::time::sleep(limits.keepalive));
240	    let start = Relay {
241	        inner: Some(inner),
242	        scan: usage,
243	        guard,
244	        icpt,
245	        ti,
246	        ctx,
247	        turn,
248	        out: VecDeque::new(),
249	        decide_queue: VecDeque::new(),
250	        pending: None,
251	        sleep,
252	    };
253	    futures::stream::unfold(start, |mut st| async move {
254	        loop {
255	            if let Some(b) = st.out.pop_front() {
256	                return Some((Ok(b), st));
257	            }
258	            // Checked before `select!`, so an elapsed timer after the end cannot spin.
259	            if st.icpt.is_finished() {
260	                st.drain_for_billing().await;
261	                return None;
262	            }
263	            st.start_next_decision();
264	            let acts = match st.next_event().await {
265	                Event::Decided(r) => {
266	                    let (hold, _) = st.pending.take().expect("the resolved decision was pending");
267	                    st.icpt.decided(hold, r, Instant::now())
268	                }
269	                Event::Wake => st.icpt.tick(Instant::now()),
270	                Event::Upstream(Some(Ok(chunk))) => {
271	                    feed_scan(&mut st.scan, &mut st.guard, &chunk);
272	                    st.icpt.push(&chunk, Instant::now())
273	                }
274	                Event::Upstream(Some(Err(_))) => {
275	                    finish_scan(&mut st.scan, &mut st.guard);
276	                    st.inner = None;
277	                    st.icpt.abort()
278	                }
279	                Event::Upstream(None) => {
280	                    finish_scan(&mut st.scan, &mut st.guard);
281	                    st.inner = None;
282	                    st.icpt.finish(Instant::now())
283	                }
284	            };
285	            st.apply(acts);
286	        }
287	    })
288	}
