343	    /// Two complete `tool_use` blocks: two holds, `Block(0)` and `Block(1)`, completed in order,
344	    /// with `gap` between the first block's end and the second block's start.
345	    fn two_tool_blocks(first: &str, second: &str, gap: Duration) -> OpenAiByteStream {
346	        let ev = |name: &str, data: String| Ok(Bytes::from(format!("event: {name}\ndata: {data}\n\n")));
347	        let block = |i: u32, name: &str| {
