382	    async fn run(decider: Arc<dyn ToolCallDecider>, limits: Limits, upstream: OpenAiByteStream) -> String {
383	        let ti = Arc::new(ToolInterception { limits, decider });
384	        let ctx = Arc::new(DecisionContext::new("principal", "scope", None));
385	        let turn = Arc::new(ToolTurn::Unavailable("unit test"));
386	        let out: Vec<Bytes> = relay(Format::AnthropicMessages, ti.limits, upstream, None, StreamUsage::Chat(UsageScanner::new()), ti, ctx, turn, TERMINAL)
387	            .map(|r| r.expect("infallible"))
388	            .collect()
389	            .await;
390	        String::from_utf8(out.concat()).expect("utf-8")
391	    }
