85	/// The gateway's HTTP surface. `/healthz` + `/readyz` are public (no auth, no body limit); the
86	/// `/v1/chat/completions` proxy is protected by the G5 auth middleware and a
87	/// [`DefaultBodyLimit`] cap; `GET /v1/service-info` (SMA-505) is protected by
88	/// [`require_authenticated`] alone, in its OWN `route_layer` group. Each protected group's
89	/// middleware is applied via [`Router::route_layer`], which runs the layers ONLY for the matched
90	/// route in THAT group — so the health probes stay outside auth AND the body limit, the
91	/// descriptor never inherits the chat group's authorization check or body limit, and an
92	/// unmatched path still 404s without first being challenged for a credential.
93	///
94	/// The discovery route deliberately does NOT join `protected`: `require_iam_auth` runs a D9
95	/// self-query authorization on top of authentication, and discovery must authenticate but never
96	/// authorize (a caller who legitimately cannot invoke the model must still be able to learn that
97	/// streaming exists). It also needs no [`DefaultBodyLimit`] — it is a GET with no body. Merging
98	/// it into `protected` would silently saddle it with both.
99	///
100	/// The shared [`AppState`] is applied ONCE, at the end, over the whole tree so the stateful
101	/// `readyz` (it probes IAM), the protected chat handler, and the descriptor handler all read the
102	/// same state. `healthz` takes no state — a stateless handler is still valid inside a stateful
103	/// router.
104	///
105	/// [`paigasus_observability::http_metrics_layer`] is applied over the whole tree (health routes
106	/// included — they get a bounded `route` label, which is acceptable). `/metrics` itself is
107	/// deliberately NOT part of this router: it is merged in by `main` (or served on its own
108	/// listener) AFTER this function returns, so a scrape never inflates its own request metrics.
109	pub fn router(state: AppState) -> Router {
110	    // The auth middlewares' state is the IAM port and the DPoP switch (`AuthState`), captured here
111	    // BEFORE the final `with_state`, and independent of the handler's `AppState`.
112	    let auth_state = AuthState {
113	        iam: state.iam.clone(),
114	        dpop_enabled: state.dpop_enabled,
115	    };
116	    let auth = axum::middleware::from_fn_with_state(auth_state.clone(), require_iam_auth);
117	    // The body-size limit: an over-limit body fails the handler's `EnvelopeBytes` extractor with
118	    // a `413` rendered inside the OpenAI envelope (SMA-588), not axum's plain text.
119	    // Note (M0): auth runs BEFORE the 413 (the limit is enforced at body extraction, after the
120	    // middleware) — acceptable here since auth reads only headers, never the body.
121	    let body_limit = DefaultBodyLimit::max(state.max_request_bytes);
122	
123	    let protected = Router::new().route("/v1/chat/completions", post(chat::chat_completions)).route_layer(auth).route_layer(body_limit);
124	
125	    // SMA-505: its own group, because discovery authenticates but does not authorize, and needs
126	    // no body limit (it is a GET). `route_layer` keeps the middleware off unmatched paths, so a
127	    // 404 is still a 404 rather than a credential challenge.
128	    let discovery_auth = axum::middleware::from_fn_with_state(auth_state, require_authenticated);
129	    let discovery = Router::new().route(paigasus_service_info::ROUTE, get(service_info::get_service_info)).route_layer(discovery_auth);
130	
131	    Router::new()
132	        .route("/healthz", get(healthz))
133	        .route("/readyz", get(readyz))
134	        .merge(protected)
135	        .merge(discovery)
136	        .layer(paigasus_observability::http_metrics_layer("gateway"))
137	        // SMA-504 D10: mirrors IAM's placement exactly — outermost, so an auth rejection is
138	        // attributable. Note this router DOES include /healthz and /readyz (unlike IAM's, which
139	        // merges them above `app_routes`), so they carry ids here; harmless and not worth
140	        // diverging the two services' composition for.
141	        .layer(paigasus_observability::CorrelationLayer)
142	        .with_state(state)
143	}
