149	/// Readiness probe: `200 {"status":"ready"}` only when the gateway can actually serve. For M0 the
150	/// meaningful hard dependency is IAM (every request introspects + authorizes against it), so
151	/// readiness turns on IAM reachability; a transient upstream blip must NOT flap readiness, so the
152	/// OpenAI upstream is checked by config-presence only (see below), never a per-poll network probe.
153	///
154	/// ## IAM reachability via a sentinel introspect (a dedicated gRPC health RPC is a follow-up)
155	/// The M0 [`Iam`] port exposes no health RPC, so reachability is inferred from a cheap sentinel
156	/// `IntrospectApiKey` with the deliberately-invalid [`READYZ_PROBE_TOKEN`]: a REACHABLE IAM parses
157	/// and rejects it, returning an application-level `Status` (e.g. `Unauthenticated`); an UNREACHABLE
158	/// IAM fails at the transport ([`IamError::Connect`], or an `Rpc` `Status` of
159	/// `Unavailable`/`DeadlineExceeded`/`Internal`). The probe is a plain parse-reject — cheap and NOT
160	/// audited (it authenticates nothing). A dedicated IAM gRPC health RPC is the documented follow-up.
161	///
162	/// Classification: transport/backend outcomes (`Connect` / `Unavailable` / `DeadlineExceeded` /
163	/// `Internal`) → NOT ready (`503`) — kept consistent with `auth::introspect_error`'s request-path
164	/// mapping so the probe reports not-ready during the same IAM failures that break real requests;
165	/// ANY other outcome (an application-level `Status` such as `Unauthenticated`, or even an `Ok`)
166	/// proves IAM answered → ready (`200`).
167	///
168	/// ## Upstream — config-presence only for M0 (a live probe is a follow-up)
169	/// `upstream.openai.{base_url,api_key}` are validated non-empty at boot by
170	/// `GatewayConfig::validate`, so there is nothing further to check here without a live network
171	/// probe on every poll (flaky + rate-costly). A live upstream-reachability probe is a documented
172	/// follow-up; deliberately NOT added here.
173	async fn readyz(State(state): State<AppState>) -> Response {
174	    match state.iam.introspect_api_key(READYZ_PROBE_TOKEN).await {
175	        // Transport/backend failures → IAM unreachable or unhealthy → not ready. `Internal` is
176	        // included so this stays consistent with `auth::introspect_error`, which maps `Internal` to
177	        // `IamUnavailable` (503) on the request path: a persistent `Internal` from IAM would
178	        // otherwise make `/readyz` report ready while every real chat request fails 503 — exactly
179	        // the outage the probe exists to catch.
180	        Err(IamError::Connect(_)) => iam_not_ready(),
181	        Err(IamError::Rpc(status)) if matches!(status.code(), tonic::Code::Unavailable | tonic::Code::DeadlineExceeded | tonic::Code::Internal) => iam_not_ready(),
182	        // Any other application-level `Status` (e.g. `Unauthenticated`) or an `Ok` proves IAM answered.
183	        Err(IamError::Rpc(_)) | Ok(_) => (StatusCode::OK, Json(json!({ "status": "ready" }))).into_response(),
184	    }
185	}
186	
187	/// The `503` readiness response when the IAM dependency is unreachable. Static, dependency-scoped,
188	/// and carries no upstream detail.
189	fn iam_not_ready() -> Response {
190	    (StatusCode::SERVICE_UNAVAILABLE, Json(json!({ "status": "not_ready", "dependency": "iam" }))).into_response()
191	}
