        let v = body(vec![
            json!({"type":"message","id":"msg_1","role":"assistant","status":"completed","content":[]}),
            fc("fc_1", "c1", "{\"a\":1}", "completed"),
            json!({"type":"custom_tool_call","id":"ctc_1","call_id":"c2","name":"sql","namespace":"db","input":"SELECT 1"}),
