}

impl RecordedRequest {
    /// The value of a request header as a `&str`, or `None` if absent / non-ASCII.
    pub fn header(&self, name: &str) -> Option<&str> {
        self.headers.get(name).and_then(|v| v.to_str().ok())
    }
}

/// How the mock should answer `POST /v1/chat/completions`.
#[derive(Clone)]
enum MockResponse {
    /// Non-stream: return `status` with the given JSON body.
    Json { status: StatusCode, body: String },
    /// Stream: return `200 text/event-stream`, emitting each element as a `data: <event>\n\n`
    /// frame IN ORDER, streamed (never buffered into one blob server-side).
    Sse { events: Vec<String> },
    /// Stream: emit ONE `data:` frame, then hold the connection open FOREVER, carrying a
    /// [`CancelGuard`] that flips `cancelled` when the response body future is dropped — i.e. when
    /// the upstream request is cancelled on client disconnect. The client-abort proof (G8).
    AbortableStream { cancelled: Arc<AtomicBool> },
    /// Non-stream, after `delay`: drives the first-byte timeout (SMA-677 A4).
    DelayedJson { delay: Duration, status: StatusCode, body: String },
    /// Stream: emit each element VERBATIM as one frame — no `data:` prefix and no terminator are
    /// added, so a test controls line endings and record shape exactly (SMA-677).
    RawSse { chunks: Vec<String> },
}

/// A Drop guard carried inside the abortable-stream response body: dropping it (which hyper does
/// when the body future is dropped on client/upstream disconnect) flips the shared cancel flag.
struct CancelGuard(Arc<AtomicBool>);

impl Drop for CancelGuard {
    fn drop(&mut self) {
        self.0.store(true, Ordering::SeqCst);
    }
}

struct MockState {
    response: MockResponse,
    recorded: Mutex<Option<RecordedRequest>>,
    requests: AtomicUsize,
}

/// A running mock OpenAI server. Its `base_url` is what you feed into [`OpenAiConfig`]; the server
/// task is aborted on drop.
pub struct MockOpenAi {
    /// `http://127.0.0.1:<port>` — pass straight to `OpenAiConfig::base_url`.
    pub base_url: String,
    state: Arc<MockState>,
    handle: tokio::task::JoinHandle<()>,
}

impl Drop for MockOpenAi {
    fn drop(&mut self) {
        self.handle.abort();
    }
}

impl MockOpenAi {
    /// Start a mock that returns a canned JSON body with the given status (the non-stream path).
    pub async fn spawn_json(status: StatusCode, body: impl Into<String>) -> Self {
        Self::spawn(MockResponse::Json { status, body: body.into() }).await
    }

    /// Start a mock that streams the given events IN ORDER as SSE `data:` frames (the stream path).
    pub async fn spawn_sse(events: Vec<String>) -> Self {
        Self::spawn(MockResponse::Sse { events }).await
    }

    /// Start a mock whose stream yields ONE `data:` frame then holds the connection open forever,
    /// carrying a Drop guard that flips the returned `Arc<AtomicBool>` when the response body
    /// future is dropped. Use it to prove client-abort → cancel-on-drop propagates end-to-end: the
    /// flag can flip ONLY as a consequence of the upstream request being cancelled.
    pub async fn spawn_abortable_stream() -> (Self, Arc<AtomicBool>) {
        let cancelled = Arc::new(AtomicBool::new(false));
        let mock = Self::spawn(MockResponse::AbortableStream { cancelled: Arc::clone(&cancelled) }).await;
        (mock, cancelled)
    }

    /// Start a mock that answers after `delay` (the non-stream path).
    pub async fn spawn_delayed_json(delay: Duration, status: StatusCode, body: impl Into<String>) -> Self {
        Self::spawn(MockResponse::DelayedJson { delay, status, body: body.into() }).await
    }

    /// Start a mock that streams each chunk verbatim (the stream path).
    pub async fn spawn_raw_sse(chunks: Vec<String>) -> Self {
        Self::spawn(MockResponse::RawSse { chunks }).await
    }

    /// How many requests reached the upstream (SMA-677: a refused request makes none).
    pub fn request_count(&self) -> usize {
        self.state.requests.load(Ordering::SeqCst)
    }

    async fn spawn(response: MockResponse) -> Self {
        let state = Arc::new(MockState {
            response,
            recorded: Mutex::new(None),
            requests: AtomicUsize::new(0),
        });
        let router = Router::new().route("/v1/chat/completions", post(handle)).with_state(state.clone());

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.expect("bind ephemeral port");
        let addr = listener.local_addr().expect("local addr");
        let base_url = format!("http://{addr}");

        let handle = tokio::spawn(async move {
            axum::serve(listener, router).await.expect("mock openai server");
        });

        MockOpenAi { base_url, state, handle }
    }

    /// The request the mock last recorded (headers + body), or `None` if none arrived yet.
    pub fn recorded(&self) -> Option<RecordedRequest> {
        self.state.recorded.lock().expect("recorded lock not poisoned").clone()
    }
}

/// Records the inbound request, then answers per the configured [`MockResponse`]. `Bytes` is the
/// body-consuming extractor, so it comes last.
async fn handle(State(state): State<Arc<MockState>>, uri: Uri, headers: HeaderMap, body: Bytes) -> Response {
    state.requests.fetch_add(1, Ordering::SeqCst);
    *state.recorded.lock().expect("recorded lock not poisoned") = Some(RecordedRequest {
        headers: headers.clone(),
        body: body.clone(),
        path: uri.path().to_owned(),
    });

    match &state.response {
        MockResponse::DelayedJson { delay, status, body } => {
            tokio::time::sleep(*delay).await;
            (*status, [(axum::http::header::CONTENT_TYPE, "application/json")], body.clone()).into_response()
        }
        MockResponse::RawSse { chunks } => {
            let stream = futures::stream::iter(chunks.clone().into_iter().map(|c| Ok::<Bytes, std::convert::Infallible>(Bytes::from(c))));
            Response::builder()
                .status(StatusCode::OK)
                .header(axum::http::header::CONTENT_TYPE, "text/event-stream")
                .body(Body::from_stream(stream))
                .expect("build sse response")
        }
        MockResponse::Json { status, body } => (*status, [(axum::http::header::CONTENT_TYPE, "application/json")], body.clone()).into_response(),
        MockResponse::Sse { events } => {
            // Stream each event as its own frame via `Body::from_stream` — genuinely streamed
            // (frame by frame) rather than concatenated into a single buffered body, so the client
            // side exercises real incremental delivery.
            let frames = events.clone();
            let stream = futures::stream::iter(frames.into_iter().map(|e| Ok::<Bytes, std::convert::Infallible>(Bytes::from(format!("data: {e}\n\n")))));
            Response::builder()
                .status(StatusCode::OK)
                .header(axum::http::header::CONTENT_TYPE, "text/event-stream")
                .body(Body::from_stream(stream))
                .expect("build sse response")
        }
        MockResponse::AbortableStream { cancelled } => {
            // A Drop guard that flips the cancel flag when the response body future is dropped.
            let guard = CancelGuard(Arc::clone(cancelled));
            let mut sent_first = false;
            // Yield ONE frame, then hold the connection open forever (`Poll::Pending`). The `move`
            // closure captures + OWNS `guard` (the `let _hold = &guard;` reference is load-bearing:
            // a `move` closure only captures what it uses), so `guard` drops exactly when this
            // stream — and hence the body future — is dropped on client/upstream disconnect,
            // flipping the flag. `Poll::Pending` with no waker registered is fine: the stream is
            // only ever advanced by the drop, never re-polled to completion.
            let stream = futures::stream::poll_fn(move |_cx| {
                if !sent_first {
                    sent_first = true;
                    return std::task::Poll::Ready(Some(Ok::<Bytes, std::convert::Infallible>(Bytes::from_static(b"data: hold\n\n"))));
                }
                let _hold = &guard;
                std::task::Poll::Pending
            });
            Response::builder()
                .status(StatusCode::OK)
                .header(axum::http::header::CONTENT_TYPE, "text/event-stream")
                .body(Body::from_stream(stream))
                .expect("build sse response")
        }
    }
}

/// Bind an ephemeral port and serve ONE connection with a chunked `text/event-stream` response that
/// sends two `data:` frames then CLOSES the socket WITHOUT the terminating `0\r\n\r\n` chunk. reqwest
/// yields the two frames and then errors on the premature EOF — exactly the mid-stream failure the
/// handler's terminal-SSE-error adapter must handle. Returns the `http://…` base URL.
pub async fn spawn_truncated_sse() -> String {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.expect("bind ephemeral port");
    let addr = listener.local_addr().expect("local addr");
    tokio::spawn(async move {
        if let Ok((mut sock, _)) = listener.accept().await {
            // Best-effort drain of the (small) request head+body so the client finishes sending.
            let mut buf = [0u8; 8192];
            let _ = sock.read(&mut buf).await;

            let frame1 = "data: first\n\n";
            let frame2 = "data: second\n\n";
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nTransfer-Encoding: chunked\r\n\r\n{l1:x}\r\n{frame1}\r\n{l2:x}\r\n{frame2}\r\n",
                l1 = frame1.len(),
                l2 = frame2.len(),
            );
            let _ = sock.write_all(response.as_bytes()).await;
            let _ = sock.flush().await;
            // Drop `sock` here -> the connection closes mid-stream (no terminating chunk).
        }
    });
    format!("http://{addr}")
}
