/// `previous_response_id`, `conversation`, `prompt`, `input`. The first match names its `param`.
fn refuse_stateful(dto: &ResponsesRequest, interception: bool) -> Result<(), GatewayError> {
    let _ = (dto, interception);
    Ok(())
}

