fn responses_limits(ti: &ToolInterception, state: &AppState) -> Limits {
    match &state.responses {
        Some(settings) => Limits {
            max_record_bytes: settings.max_record_bytes,
            max_held_bytes: settings.max_held_bytes,
            ..ti.limits
        },
        None => ti.limits,
    }
}
